-- Quest completion texts (quest_offer_reward) and progress texts (quest_request_items) from EG Link for every quest of this
-- world that has no text, an empty text, or a placeholder text (VerifiedBuild -1, as 2026_11_08_20 and the later
-- placeholder quests write). Written to work on any world: the full EG Link list goes into a temporary table and only
-- quests that exist in quest_template are touched; a real existing text (VerifiedBuild not -1, not empty) is never replaced.
-- Sorts after every other world file so later placeholder files can't put their placeholder back over it.
-- Data from Efficient Games (https://efficient.games), licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).
-- Source: EG Link output, github.com/JIVESCORP/eg-link-output-wowf commit 9fcae73c (data to 2026-11-10), texts.enUS.json,
-- newest live build first (70862, 70840, 70790, older live builds, then the Forever beta), the variant most players saw.
-- Changed: line breaks written as $B, rows written as TrinityCore rows. VerifiedBuild = the build the text was seen on.
-- Safe to run again.

DROP TEMPORARY TABLE IF EXISTS `eglink_offer_reward`;
CREATE TEMPORARY TABLE `eglink_offer_reward` (`ID` int unsigned NOT NULL PRIMARY KEY, `Txt` mediumtext NOT NULL, `Build` int NOT NULL);
SELECT e.`ID`, e.`Txt`, e.`Build` FROM `eglink_offer_reward` e JOIN `quest_template` q ON q.`ID` = e.`ID`
ON DUPLICATE KEY UPDATE
  `RewardText` = IF(`quest_offer_reward`.`VerifiedBuild` = -1 OR `quest_offer_reward`.`RewardText` IS NULL OR `quest_offer_reward`.`RewardText` = '', VALUES(`RewardText`), `quest_offer_reward`.`RewardText`),
  `VerifiedBuild` = IF(`quest_offer_reward`.`RewardText` = VALUES(`RewardText`), VALUES(`VerifiedBuild`), `quest_offer_reward`.`VerifiedBuild`);
DROP TEMPORARY TABLE `eglink_offer_reward`;

DROP TEMPORARY TABLE IF EXISTS `eglink_request_items`;
CREATE TEMPORARY TABLE `eglink_request_items` (`ID` int unsigned NOT NULL PRIMARY KEY, `Txt` mediumtext NOT NULL, `Build` int NOT NULL);
SELECT e.`ID`, e.`Txt`, e.`Build` FROM `eglink_request_items` e JOIN `quest_template` q ON q.`ID` = e.`ID`
ON DUPLICATE KEY UPDATE
  `CompletionText` = IF(`quest_request_items`.`VerifiedBuild` = -1 OR `quest_request_items`.`CompletionText` IS NULL OR `quest_request_items`.`CompletionText` = '', VALUES(`CompletionText`), `quest_request_items`.`CompletionText`),
  `VerifiedBuild` = IF(`quest_request_items`.`CompletionText` = VALUES(`CompletionText`), VALUES(`VerifiedBuild`), `quest_request_items`.`VerifiedBuild`);
DROP TEMPORARY TABLE `eglink_request_items`;
